      $('#o-sc-n',sc).textContent='Da '+eur.format(s.price)+' a '+eur.format(s.max)+' pr. m² + moms afhængigt af partiet: i kurven regner vi med '+eur.format(s.price)+'/m², den endelige pris bekræfter vi.';
      var i=$('#o-mq',sc);if(i&&document.activeElement!==i)i.value=c.mq;
      $('#s-pm-dims').textContent=mqF(c.mq)+' m²';
