    if(q)h+='<fieldset class="s-opt"><legend>Længde <small>'+K.big.min+'–'+K.big.max+' cm, op til</small></legend><div class="s-chips" id="o-bw">'+[150,180,250].map(function(w){return '<button type="button" class="s-chip" data-v="'+w+'">'+w+' cm</button>'}).join('')+'</div><div class="s-dims one"><label>Længde (cm)<input type="number" inputmode="numeric" id="o-w" min="'+K.big.min+'" max="'+K.big.max+'"></label></div></fieldset>'
