        f.innerHTML='<div class="s-sums"><div><span>Subtotal</span><b>'+eur.format(K.sub)+'</b></div>'+(K.disc?'<div class="s-sum-off"><span>Rabatter</span><b>−'+eur.format(K.disc)+'</b></div>':'')+'<div class="s-total"><span>Vejledende total</span><b id="s-tot">'+eur.format(K.tot)+'</b></div></div>'
          +nudge
          +(code?'<div class="s-code ok">'+IC.check+'<span>Kode <b>'+esc(code)+'</b> aktiv: −'+N.perc+'% på hvert produkt<small class="s-code-left">Udløber om '+leftTxt(codeLeft())+': bestil inden da, så du ikke mister den</small></span><button type="button" id="s-code-rm" aria-label="Fjern kode">'+IC.x+'</button></div>'
               :(codeExpired()?'<div class="s-code exp"><span>Koden '+esc(N.code)+' er udløbet: den gjaldt i '+N.validDays+' dage efter tilmeldingen.</span></div>':'')+'<form class="s-code" id="s-code-f"><input id="s-code-in" placeholder="Rabatkode" aria-label="Rabatkode" autocomplete="off"><button type="submit">Anvend</button></form>'+(N.perc&&!nlDone()?'<button type="button" class="s-nl-mini" data-nl-open>Har du ingen kode? <b>Tilmeld dig og spar '+eur.format(Math.round(K.sub*N.perc/100))+'</b></button>':''))
          +payHTML()+assureHTML(ex)+(window.PDA?'<button type="button" class="s-btn s-btn-p s-btn-cta" id="s-checkout">Send bestillingen<small>vi kontakter dig for at bekræfte</small></button>':'')
